(* [comment removed for export] *)
(* [comment removed for export] *)

Definition P_OTF_RET : Z := 0x31eb4.   (* [comment removed for export] *)
Definition OTF_SEGA_STACK : Z := 304.   (* [comment removed for export] *)

Definition otf_frame (m : mem) (sp ra s0 s1 s2 s3 s4 s5 : word) (j8 : list byte) (w1 w2 w3 w4 : word) : Prop :=
  rw_cells rsegs m (bv_unsigned sp + -96) [CB 8 j8; C8 w1; C8 w2; C8 w3; C8 w4; C8 s5; C8 s4; C8 s3; C8 s2; C8 s1; C8 s0; C8 ra].

Definition otf_segA_post (ra sp gp tp s0 s1 s2 s3 s4 s5 s6 s7 s8 s9 s10 s11 : word) (F : bvmap 5 word) (fc : bv 32)
    (P f np vp ecA : Z) (name value : list byte) (S L : list Z) (ns : NS) (ls : LS) (em : gmap Z elt) (lo : Z) (m : mem)
    : machine_state -> Prop :=
  fun ms' => exists (kept : bool) t0 t1 t2 a0 a1 a2 a3 a4 a5 a6 a7 t3 t4 t5 t6 m' j8 w1 w2 w3 w4,
    munch [(lo, bv_unsigned sp)]%Z m m' /\ wmono rsegs m m' /\ mem_inv rsegs m'
    /\ FieldsC m' (P + 80) S L ns ls em /\ FT m'
    /\ if kept then
         ms' = MS (mkR (Z_to_bv 64 P_OTF_RET) (Z_to_bv 64 (bv_unsigned sp + -96)) gp tp t0 t1 t2 (Z_to_bv 64 ecA) (Z_to_bv 64 (zlength value))
                       (Z_to_bv 64 (P + 80)) (Z_to_bv 64 f) (Z_to_bv 64 np) (Z_to_bv 64 (zlength name)) (Z_to_bv 64 vp) (Z_to_bv 64 (zlength value)) (Z_to_bv 64 ecA) a7
                       (Z_to_bv 64 vp) (Z_to_bv 64 f) (Z_to_bv 64 (P + 80)) (Z_to_bv 64 P) s6 s7 s8 s9 s10 s11 t3 t4 t5 t6)
                  F (Z_to_bv 64 P_FIELDS_INSERT) fc None m' (seg_rom rsegs)
         /\ stk rsegs m' lo (bv_unsigned sp + -96)
         /\ otf_frame m' sp ra s0 s1 s2 s3 s4 s5 j8 w1 w2 w3 w4
       else
         ms' = MS (mkR ra sp gp tp t0 t1 t2 s0 s1 a0 a1 a2 a3 a4 a5 a6 a7 s2 s3 s4 s5 s6 s7 s8 s9 s10 s11 t3 t4 t5 t6)
                  F (ret_pc ra) fc None m' (seg_rom rsegs)
         /\ stk rsegs m' lo (bv_unsigned sp).

Definition otf_segA_stmt : Prop := forall (P f np vp ecA : Z) (mb : byte) (name value : list byte) (S L : list Z) (ns : NS) (ls : LS) (em : gmap Z elt) (lo : Z)
    ra sp gp tp t0 t1 t2 s0 s1 a7 s2 s3 s4 s5 s6 s7 s8 s9 s10 s11 t3 t4 t5 t6
    (F : bvmap 5 word) fc (m : mem),
  FieldsC m (P + 80) S L ns ls em -> FT m -> rw_cells rsegs m (P + 242) [C1 mb] ->
  bytes_at rsegs m np name -> np + zlength name < 2^64 -> (np + zlength name <= lo \/ bv_unsigned sp <= np) ->
  0 <= f < 2^64 -> 0 <= vp < 2^64 -> zlength value < 2^64 -> 0 <= ecA < 2^64 ->
  stk rsegs m lo (bv_unsigned sp) -> lo + OTF_SEGA_STACK <= bv_unsigned sp -> hceil <= lo -> bv_unsigned sp <= P -> P + 243 <= 2^64 ->
  mem_inv rsegs m ->
  evt rsegs (otf_segA_post ra sp gp tp s0 s1 s2 s3 s4 s5 s6 s7 s8 s9 s10 s11 F fc P f np vp ecA name value S L ns ls em lo m)
    (MS (mkR ra sp gp tp t0 t1 t2 s0 s1 (Z_to_bv 64 P) (Z_to_bv 64 f) (Z_to_bv 64 np) (Z_to_bv 64 (zlength name))
              (Z_to_bv 64 vp) (Z_to_bv 64 (zlength value)) (Z_to_bv 64 ecA) a7 s2 s3 s4 s5 s6 s7 s8 s9 s10 s11 t3 t4 t5 t6)
        F (Z_to_bv 64 P_ON_TRAILER_FIELD_IMPL) fc None m (seg_rom rsegs)).


